-- Server-only readiness probe for atomic TVOD rental fulfillment.
create or replace function public.loop_rental_fulfillment_ready()
returns boolean
language sql
security invoker
set search_path = ''
as $function$
  select
    pg_catalog.to_regclass('public.loop_payment_events') is not null
    and pg_catalog.to_regclass('public.loop_user_tvod_entitlements') is not null
    and pg_catalog.to_regprocedure(
      'public.loop_fulfill_captured_rental(text,text,uuid,text,timestamptz,timestamptz)'
    ) is not null;
$function$;

revoke all on function public.loop_rental_fulfillment_ready() from public, anon, authenticated;
grant execute on function public.loop_rental_fulfillment_ready() to service_role;

-- StreamVista customer-owned project intake foundation.
-- Apply to an isolated StreamVista test environment first; do not apply to shared production until certified.
create extension if not exists pgcrypto;

create table if not exists public.streamvista_projects (
  id uuid primary key default gen_random_uuid(),
  owner_user_id uuid not null references auth.users(id) on delete cascade,
  title text not null check (char_length(title) between 2 and 160),
  service_id text not null check (service_id in ('localization','dubbing','audio_description','post_production','ott_delivery','campaign_assets')),
  service_mode text not null check (service_mode in ('self_service','studio_assisted')),
  source_language text,
  target_language text,
  requirements text not null check (char_length(requirements) between 10 and 5000),
  rights_confirmed boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.streamvista_service_orders (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references public.streamvista_projects(id) on delete cascade,
  owner_user_id uuid not null references auth.users(id) on delete cascade,
  request_key uuid not null,
  quote_status text not null default 'pending_scope' check (quote_status in ('pending_scope','quoted','accepted','declined','expired')),
  quote_amount_paise bigint check (quote_amount_paise is null or quote_amount_paise > 0),
  currency text not null default 'INR' check (currency = 'INR'),
  order_status text not null default 'requested' check (order_status in ('requested','awaiting_customer','confirmed','cancelled')),
  payment_status text not null default 'not_started' check (payment_status in ('not_started','pending','paid','failed','refunded')),
  processing_status text not null default 'not_started' check (processing_status in ('not_started','queued','processing','human_review','qc','approved','failed','delivered')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (owner_user_id, request_key)
);

create index if not exists streamvista_projects_owner_created_idx
  on public.streamvista_projects (owner_user_id, created_at desc);
create index if not exists streamvista_orders_owner_created_idx
  on public.streamvista_service_orders (owner_user_id, created_at desc);
create index if not exists streamvista_orders_project_idx
  on public.streamvista_service_orders (project_id);

alter table public.streamvista_projects enable row level security;
alter table public.streamvista_service_orders enable row level security;

-- No direct browser access. All writes/read paths are authenticated server endpoints.
revoke all on public.streamvista_projects from anon, authenticated;
revoke all on public.streamvista_service_orders from anon, authenticated;
grant all on public.streamvista_projects to service_role;
grant all on public.streamvista_service_orders to service_role;

create or replace function public.create_streamvista_customer_order(
  p_owner_user_id uuid,
  p_request_key uuid,
  p_title text,
  p_service_id text,
  p_service_mode text,
  p_source_language text,
  p_target_language text,
  p_requirements text,
  p_rights_confirmed boolean
)
returns table(project_id uuid, order_id uuid, reused boolean)
language plpgsql
security invoker
set search_path = pg_catalog, public
as $$
declare
  v_project_id uuid;
  v_order_id uuid;
  v_existing record;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_owner_user_id::text || p_request_key::text, 0));

  if p_owner_user_id is null or p_request_key is null
    or p_title is null or char_length(trim(p_title)) not between 2 and 160
    or p_requirements is null or char_length(trim(p_requirements)) not between 10 and 5000
    or p_service_id not in ('localization','dubbing','audio_description','post_production','ott_delivery','campaign_assets')
    or p_service_mode not in ('self_service','studio_assisted')
    or p_rights_confirmed is distinct from true then
    raise exception 'invalid StreamVista project input' using errcode = '22023';
  end if;

  select o.id, o.project_id, p.title, p.service_id, p.service_mode,
         p.source_language, p.target_language, p.requirements
    into v_existing
    from public.streamvista_service_orders o
    join public.streamvista_projects p on p.id = o.project_id
   where o.owner_user_id = p_owner_user_id and o.request_key = p_request_key;

  if found then
    if v_existing.title <> trim(p_title)
      or v_existing.service_id <> p_service_id
      or v_existing.service_mode <> p_service_mode
      or coalesce(v_existing.source_language,'') <> coalesce(nullif(trim(coalesce(p_source_language,'')),''),'')
      or coalesce(v_existing.target_language,'') <> coalesce(nullif(trim(coalesce(p_target_language,'')),''),'')
      or v_existing.requirements <> trim(p_requirements) then
      raise exception 'request key already used with different project details' using errcode = '23505';
    end if;
    return query select v_existing.project_id, v_existing.id, true;
    return;
  end if;

  insert into public.streamvista_projects (
    owner_user_id, title, service_id, service_mode, source_language,
    target_language, requirements, rights_confirmed
  ) values (
    p_owner_user_id, trim(p_title), p_service_id, p_service_mode,
    nullif(trim(coalesce(p_source_language,'')), ''),
    nullif(trim(coalesce(p_target_language,'')), ''),
    trim(p_requirements), true
  ) returning id into v_project_id;

  insert into public.streamvista_service_orders (
    project_id, owner_user_id, request_key
  ) values (
    v_project_id, p_owner_user_id, p_request_key
  ) returning id into v_order_id;

  return query select v_project_id, v_order_id, false;
end;
$$;

revoke all on function public.create_streamvista_customer_order(uuid,uuid,text,text,text,text,text,text,boolean) from public, anon, authenticated;
grant execute on function public.create_streamvista_customer_order(uuid,uuid,text,text,text,text,text,text,boolean) to service_role;

create table if not exists bridge_private.buyer_organization_verifications (
  organization_id uuid primary key references public.bridge_organizations(id) on delete restrict,
  buyer_kind text not null
    check (buyer_kind in ('buyer','platform_buyer','distributor','aggregator')),
  verification_status text not null default 'pending_review'
    check (verification_status in ('unverified','pending_review','verified','rejected','suspended')),
  legal_registration_country text,
  legal_registration_number text,
  official_website text,
  submitted_by text not null,
  submitted_at timestamptz not null default now(),
  reviewed_by text,
  reviewed_at timestamptz,
  review_notes text,
  updated_at timestamptz not null default now(),
  constraint buyer_org_verification_review_check
    check ((verification_status in ('verified','rejected','suspended') and reviewed_by is not null and reviewed_at is not null)
        or (verification_status in ('unverified','pending_review') and (reviewed_by is null or reviewed_at is not null)))
);

create table if not exists bridge_private.buyer_organization_verification_evidence (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references bridge_private.buyer_organization_verifications(organization_id) on delete restrict,
  evidence_kind text not null
    check (evidence_kind in ('company_registration','tax_registration','board_resolution','authorized_signatory','platform_ownership','other')),
  storage_object_path text not null,
  sha256_hex text,
  uploaded_by text not null,
  uploaded_at timestamptz not null default now(),
  review_status text not null default 'pending'
    check (review_status in ('pending','accepted','rejected')),
  reviewed_by text,
  reviewed_at timestamptz,
  review_notes text,
  constraint buyer_org_evidence_sha_check
    check (sha256_hex is null or sha256_hex ~ '^[0-9a-fA-F]{64}$'),
  constraint buyer_org_evidence_review_check
    check ((review_status = 'pending' and reviewed_by is null and reviewed_at is null)
        or (review_status <> 'pending' and reviewed_by is not null and reviewed_at is not null))
);

create index if not exists buyer_org_verification_status_idx
  on bridge_private.buyer_organization_verifications (verification_status, buyer_kind);
create index if not exists buyer_org_verification_evidence_org_idx
  on bridge_private.buyer_organization_verification_evidence (organization_id, uploaded_at desc);

alter table bridge_private.buyer_organization_verifications enable row level security;
alter table bridge_private.buyer_organization_verification_evidence enable row level security;

drop policy if exists deny_browser_access on bridge_private.buyer_organization_verifications;
create policy deny_browser_access on bridge_private.buyer_organization_verifications
  for all to anon, authenticated using (false) with check (false);
drop policy if exists deny_browser_access on bridge_private.buyer_organization_verification_evidence;
create policy deny_browser_access on bridge_private.buyer_organization_verification_evidence
  for all to anon, authenticated using (false) with check (false);

revoke all on bridge_private.buyer_organization_verifications from anon, authenticated;
revoke all on bridge_private.buyer_organization_verification_evidence from anon, authenticated;
grant select, insert, update, delete on bridge_private.buyer_organization_verifications to service_role;
grant select, insert, update, delete on bridge_private.buyer_organization_verification_evidence to service_role;

comment on table bridge_private.buyer_organization_verifications is
  'Server-only legal identity verification state for buyer organizations; does not alter the shared organization record.';
comment on table bridge_private.buyer_organization_verification_evidence is
  'Server-only evidence metadata for buyer legal identity verification; document bytes remain in private object storage.';

-- CMS homepage content storage.
-- Forward-only additive migration. Public clients must not read/write this table;
-- the application serves public homepage content through its server-side getter.
CREATE TABLE IF NOT EXISTS public.bridge_site_content (
  content_key text PRIMARY KEY,
  hero_title text NOT NULL,
  hero_body text NOT NULL,
  workflow_heading text NOT NULL,
  audience_heading text NOT NULL,
  final_cta_heading text NOT NULL,
  updated_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.bridge_site_content ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.bridge_site_content FROM anon, authenticated;

